import{_ as t,o as r,c as a,a2 as o}from"./chunks/framework.BXA5Pi9t.js";const d=JSON.parse('{"title":"Ceph Performance Meeting 2022-05-05","description":"","frontmatter":{"title":"Ceph Performance Meeting 2022-05-05","date":"2022-05-05T00:00:00.000Z","updated":"2022-05-07T00:00:00.000Z","tags":["Ceph","分布式存储","CRUSH算法","性能优化","高可用性"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2022/Ceph_Performance_Meeting_2022-05-05.md","filePath":"posts/2022/Ceph_Performance_Meeting_2022-05-05.md","lastUpdated":1780460162000}'),l={name:"posts/2022/Ceph_Performance_Meeting_2022-05-05.md"};function s(i,e,n,g,_,c){return r(),a("div",null,[...e[0]||(e[0]=[o('<h3 id="会议纪要" tabindex="-1">会议纪要 <a class="header-anchor" href="#会议纪要" aria-label="Permalink to &quot;会议纪要&quot;">​</a></h3><p><strong>日期：2022-05-05</strong><strong>参会人员：未提及</strong></p><h4 id="_1-已解决的问题和已完成的prs" tabindex="-1">1. 已解决的问题和已完成的PRs <a class="header-anchor" href="#_1-已解决的问题和已完成的prs" aria-label="Permalink to &quot;1. 已解决的问题和已完成的PRs&quot;">​</a></h4><ul><li><strong>Adam的卓越PR</strong>：解决了Quarry&#39;s PR中的边界检查问题，通过不进行整个空间迭代器边界检查，使之前失败的测试得以通过。</li><li><strong>Cory的PR</strong>：已重新纳入pacific版本，可能已回退主版本。该PR和atom六都将被纳入1628版本及master版本，进展顺利。</li><li><strong>参数解析修复</strong>：收到Kefu和Radic的良好反馈，代码质量提升，已正确传递星号命令行选项给c-star，解决传递问题。</li></ul><h4 id="_2-更新的prs和待解决问题" tabindex="-1">2. 更新的PRs和待解决问题 <a class="header-anchor" href="#_2-更新的prs和待解决问题" aria-label="Permalink to &quot;2. 更新的PRs和待解决问题&quot;">​</a></h4><ul><li><strong>启用TC Malik的更新</strong>：当使用CStar时，发现如果编译Ceph支持CStar，则neither Crimson还是Classic OSD将不会使用alec，而是都回退到使用lipsy。更新更改了条件判断逻辑，以防止在使用CStar时链接TC Malloc。</li><li><strong>遇到的问题</strong>：目前遇到一些无效指针断言，似乎源自地址消毒器。Matan正在查看此问题，认为追踪到的问题源于TC Malloc的已知行为。此外，在运行的一些测试中发现了sink故障，可能是由此或其他因素引起。相关PR可能会暂时搁置。</li></ul><h4 id="_3-未来计划和行动项" tabindex="-1">3. 未来计划和行动项 <a class="header-anchor" href="#_3-未来计划和行动项" aria-label="Permalink to &quot;3. 未来计划和行动项&quot;">​</a></h4><ul><li><strong>基于时间的Near-Fit算法</strong>：PR需要重新定位和更新，建议使用旧版本的配置选项以减少热路径性能的影响。</li><li><strong>RGW Deus Cell实现</strong>：可能需要更多审查，并且现在需要重新定位。作者需要进一步操作。</li><li><strong>增加测试覆盖率</strong>：特别是围绕迭代器工作方式，以提高代码质量和防止未来的回归。</li><li><strong>解决Aborts和Sig Faults</strong>：这是优先事项，特别是为了能够进行更广泛的性能和压力测试。</li><li><strong>Igor的工作评估</strong>：开始评估Igor实现的BlueStore Wall的工作，而不是使用RoxDB1。新机制尚未在BlueStore中启用，需要进一步调查原因。</li></ul><p><strong>下一步行动</strong>：</p><ul><li>继续跟踪与TC Malloc相关的问题并解决。</li><li>提高迭代器工作的测试覆盖率。</li><li>确定是否继续使用传统选项或转向新的配置方式。</li><li>关注并帮助解决Crimson的性能瓶颈和挂起问题。</li><li>深入理解和评估BlueStore Wall的实现和效果。</li></ul><p><strong>会议结束</strong>：会议提前结束，祝大家有一个美好的一周，并期待下周的会议。</p>',11)])])}const h=t(l,[["render",s]]);export{d as __pageData,h as default};
